import { describe, it, beforeEach, afterEach } from "node:test";
import assert from "node:assert";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { createL1Stub } from "./helpers/l1-stub.ts";

describe("L1 harness", () => {
  let tmp: string;

  beforeEach(() => {
    tmp = mkdtempSync(join(tmpdir(), "pi-telemetry-l1-"));
  });

  afterEach(() => {
    try {
      rmSync(tmp, { recursive: true, force: true });
    } catch { /* ignore */ }
  });

  it("stub-fired event writes a row", async () => {
    const stub = createL1Stub();
    const dbPath = join(tmp, "telemetry.db");
    const { DatabaseSync } = await import("node:sqlite");
    const db = new DatabaseSync(dbPath);
    db.exec(`
      CREATE TABLE telemetry_meta (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        unix_ms INTEGER NOT NULL,
        level TEXT NOT NULL,
        event TEXT NOT NULL
      );
    `);

    stub.pi.on("session_start", async () => {
      db.prepare("INSERT INTO telemetry_meta (unix_ms, level, event) VALUES (?, ?, ?)").run(
        Date.now(),
        "warn",
        "l1-test",
      );
    });

    await stub.fire("session_start", { reason: "startup" });

    const count = db
      .prepare("SELECT COUNT(*) AS c FROM telemetry_meta WHERE event = 'l1-test'")
      .get() as { c: number };
    assert.strictEqual(count.c, 1);
    db.close();
  });
});

